import { CATALOG_ENTRIES, EXPERIENCE_CATEGORY_ORDER } from "@aether/shared";

/**
 * Public /integrations directory — DERIVED VIEW of the canonical catalog.
 *
 * THIS MODULE IS NOT A SECOND TAXONOMY.
 *
 * The canonical source of truth for Aether's connectable integrations is the
 * generated TypeScript mirror `packages/shared/connector-taxonomy.ts`
 * (WS-6 tail, generated by scripts/generate_connector_taxonomy.py — never
 * hand-edited), which mirrors the backend one-customer catalog
 *
 *   Backend Architecture/aether-backend/shared/integration_contracts/
 *     catalog.py      (ProviderManifest catalog ALL_MANIFESTS four-group union)
 *     experience.py   (ExperienceCategory + category→experience projection)
 *
 * The directory rows below are PROJECTED at module load from that mirror's
 * CATALOG_ENTRIES, not transcribed: this file selects the two catalog groups
 * Aether's public surfaces advertise as connectable and maps each selected
 * entry onto a ConnectorRecord. Family ids, display names, engineering
 * categories, the customer-facing experience_category projection, readiness
 * state, authentication and webhook support all come from the shared entry —
 * there is no hand-copied vocabulary left in this file to drift.
 *
 * SCOPE OF THE PUBLIC SUBSET — the two catalog groups Aether's public surfaces
 * advertise as connectable, every entry at the availability state the runtime
 * records (all `credential_waiting`, never shown as live):
 *
 *   1. the 21 inbound connector-registry families (BYOD ingestion, `product:
 *      'ingestion', capability: 'connector'`, in registry insertion order), and
 *   2. the 7 measurement ad-platform families (`product: 'ads', capability:
 *      'metrics'`, in catalog AD_FAMILIES order), exposed by the catalog as
 *      product "ads" / capability "metrics".
 *
 * Deliberately NOT listed here:
 *   - payment rails (observe-only financial rails; several share a family name
 *     with an ingestion connector, e.g. stripe, so listing both would read as a
 *     duplicate to a public visitor), and
 *   - deferred credit bureaus (SCAFFOLDED, tenant-invisible, enabled in no
 *     environment — catalog.py §26). Neither group has a public connect story
 *     yet, and the directory never fabricates capability behind a name.
 *
 * READINESS POSTURE — same bar as the R1/R2 snapshot: every projected entry is
 * credential-gated (catalog readiness_state maps to CredentialReadiness
 * "credential_waiting" → level 3 in the catalog, visible in local/integration,
 * never staging/production). None is replay/sandbox/partner-validated today, so
 * none is rendered as live.
 *
 * MARKETING OVERLAY — the catalog carries no public marketing voice. Two fields
 * are therefore provided locally, keyed by canonical family id in PUBLIC_COPY:
 * the directory's description copy and its `pull` posture (the catalog mirrors
 * webhook support and incremental sync but not the descriptor's supports_pull).
 * A catalog family that enters either public group without a copy entry fails
 * loudly at module load rather than shipping a descriptionless row, and
 * connectors.test.ts pins the subset snapshot so it cannot silently grow.
 *
 * Experience labels, readiness labels and the boundary alias map (aliases.py,
 * ADR-0009) are also marketing/compatibility voice pinned below; the alias map
 * still resolves legacy names to canonical catalog families and never invents a
 * row of its own.
 */

export type ConnectorAuth = "api_key" | "webhook_only" | "none";

/** Real readiness tokens (marketing subset of shared/certification/readiness.py
 * CredentialReadiness). The full backend vocabulary also carries
 * credential_supplied / connection_validated / suspended / revoked, but no
 * catalog family is in those states today, so they are not in this union. */
export type ConnectorReadiness =
  | "scaffolded"
  | "disabled"
  | "degraded"
  | "credential_waiting"
  | "replay_validated"
  | "sandbox_validated"
  | "partner_live";

/**
 * Customer-facing experience categories — re-exported verbatim from the
 * generated mirror (shared/integration_contracts/experience.py
 * ExperienceCategory order, ADR-0010). Wire tokens are stable and are the
 * vocabulary the tenant Settings→Integrations surface groups by; the public
 * directory derives one experience per connector from the catalog entry's own
 * experience_category projection, never a local rule table.
 */
export type ExperienceToken = (typeof EXPERIENCE_CATEGORY_ORDER)[number];

/** Canonical experience categories in experience.py's stable presentation order
 * (EXPERIENCE_CATEGORY_ORDER). Only tokens actually present in the subset
 * surface as facets, but the full canonical set is exported so a label lookup
 * or a handoff never invents a token. */
export const EXPERIENCE_CATEGORIES: readonly ExperienceToken[] =
  EXPERIENCE_CATEGORY_ORDER;

/** Public marketing voice for each experience token (UX copy invariants §6:
 * Integrations, Connect, Manage, Advertising, Commerce & Revenue, Customer &
 * CRM, Communications, Analytics & Behavior…). Engineering category tokens stay
 * internal; this label map is what surfaces publicly. */
export const EXPERIENCE_LABELS: Readonly<Record<ExperienceToken, string>> = {
  advertising_campaigns: "Advertising",
  commerce_revenue: "Commerce & Revenue",
  crm_customer: "Customer & CRM",
  communications_lifecycle: "Communications",
  analytics_behavior: "Analytics & Behavior",
  social_community: "Social",
  customer_support: "Customer support",
  work_operations: "Work & operations",
};

export interface ConnectorRecord {
  /** Canonical catalog family id (connector_type / ad family), e.g. 'stripe',
   * 'google_ads' — read from the shared catalog entry. The unified catalog keys
   * on these ids — never a legacy alias (twitter_ads resolves to x_ads,
   * google_analytics to ga4, …). */
  readonly id: string;
  /** Public display label — the catalog's display_name (descriptor label /
   * catalog AD_DISPLAY_NAMES). */
  readonly name: string;
  /** Canonical engineering category token the catalog entry carries
   * (ConnectorCategory literal or "ad_platform"), kept as the catalog's token,
   * never surfaced as the primary public grouping. */
  readonly category: string;
  /** Public marketing copy (PUBLIC_COPY overlay — the catalog carries no
   * description voice). The observe-only comms sentence ("Aether never sends
   * through this connector.") is part of the honest copy and is preserved. */
  readonly description: string;
  /** Authentication token projected by the catalog entry's `authentication`
   * field (webhook_and_not-pull → 'webhook_only'; requires_secret → 'api_key';
   * else 'none'). Ad platforms are token-paste 'api_key' (no Aether-driven
   * OAuth yet). */
  readonly auth: ConnectorAuth;
  /** supports_pull — the descriptor does not project onto a catalog field, so
   * this posture is part of the marketing overlay (see module docstring). */
  readonly pull: boolean;
  /** supports_webhook — projected from the catalog entry's
   * `webhooks_supported`. */
  readonly webhook: boolean;
  /** Readiness token mapped from the catalog entry's `readiness_state` (see
   * module docstring). */
  readonly status: ConnectorReadiness;
  /** Every listed family is read-inbound: Aether reads provider activity in and
   * never pushes outbound today. */
  readonly dataDirection: "inbound";
  /** Customer-facing experience projected by the catalog entry's
   * `experience_category` (never hand-assigned per record). */
  readonly experience: ExperienceToken;
}

/** Marketing voice the catalog does not carry, keyed by canonical family id.
 * `pull` mirrors the descriptor's supports_pull posture for the family; the
 * catalog mirrors webhook support and incremental sync but not supports_pull.
 * Every public-subset family must have an entry here or module load throws. */
type PublicCopy = {
  readonly description: string;
  readonly pull: boolean;
};

