type CatalogEntry = (typeof CATALOG_ENTRIES)[number];

function isExperienceToken(value: string | null): value is ExperienceToken {
  return (
    value !== null &&
    (EXPERIENCE_CATEGORY_ORDER as readonly string[]).includes(value)
  );
}

const READINESS_TOKENS: readonly ConnectorReadiness[] = [
  "scaffolded",
  "disabled",
  "degraded",
  "credential_waiting",
  "replay_validated",
  "sandbox_validated",
  "partner_live",
];

function assertReadiness(value: string): ConnectorReadiness {
  if (!(READINESS_TOKENS as readonly string[]).includes(value)) {
    throw new Error(
      `connectors.ts: catalog readiness_state "${value}" has no ConnectorReadiness token. ` +
        "Extend the readiness vocabulary in shared/certification/readiness.py and mirror it here.",
    );
  }
  return value as ConnectorReadiness;
}

function assertAuth(value: string): ConnectorAuth {
  if (value === "api_key" || value === "webhook_only" || value === "none") {
    return value;
  }
  throw new Error(
    `connectors.ts: catalog authentication "${value}" is not a public ConnectorAuth token.`,
  );
}

/** The two catalog groups the public directory advertises as connectable:
 * ingestion connectors (`product: 'ingestion', capability: 'connector'`) and
 * measurement ad platforms (`product: 'ads', capability: 'metrics'`). */
function isPublicDirectoryEntry(entry: CatalogEntry): boolean {
  if (entry.capability === "connector" && entry.product === "ingestion") {
    return true;
  }
  if (entry.product === "ads" && entry.capability === "metrics") {
    return true;
  }
  return false;
}

const PUBLIC_SUBSET_COUNT = 28; // 21 registry families + 7 measurement ad platforms

/** Project one catalog entry onto a public ConnectorRecord. Every structural
 * field is read from the shared entry; only description/pull come from the
 * marketing overlay. */
function project(entry: CatalogEntry): ConnectorRecord {
  const copy = PUBLIC_COPY[entry.family];
  if (copy === undefined) {
    throw new Error(
      `connectors.ts: catalog family "${entry.family}" entered the public directory ` +
        "subset but has no marketing PUBLIC_COPY entry. Add its description copy before it ships.",
    );
  }
  const experience = entry.experience_category;
  if (!isExperienceToken(experience)) {
    throw new Error(
      `connectors.ts: catalog family "${entry.family}" carries no public experience_category ` +
        `("${String(experience)}"). Only catalog groups with a customer-facing experience project here.`,
    );
  }
  return {
    id: entry.family,
    name: entry.display_name,
    category: entry.category,
    description: copy.description,
    auth: assertAuth(entry.authentication),
    pull: copy.pull,
    webhook: entry.webhooks_supported,
    status: assertReadiness(entry.readiness_state),
    dataDirection: "inbound",
    experience,
  };
}

const publicEntries = CATALOG_ENTRIES.filter(isPublicDirectoryEntry);
if (publicEntries.length !== PUBLIC_SUBSET_COUNT) {
  throw new Error(
    `connectors.ts: expected ${PUBLIC_SUBSET_COUNT} public connectable families in the ` +
      `catalog mirror, found ${publicEntries.length}. Update PUBLIC_SUBSET_COUNT and the ` +
      "PUBLIC_COPY overlay (and connectors.test.ts) together when the catalog grows a public group.",
  );
}

/**
 * The public connectable subset, in the mirror's stable order: the 21
 * connector-registry families in registry insertion order, then the 7
 * measurement ad-platform families in catalog.py's AD_FAMILIES order.
 */
export const CONNECTORS: readonly ConnectorRecord[] = publicEntries.map(
  (entry) => project(entry),
);

/** Canonical family ids present in the public subset — the whitelist a public
 * page may hand off with (a connect deep-link never names a fabricated family). */
export const DIRECTORY_FAMILY_IDS: readonly string[] = CONNECTORS.map(
  (connector) => connector.id,
);

/** Sorted unique engineering categories present in the subset (catalog
 * category tokens). Kept for the directory's technical "Filter by category"
 * facet. */
export const CONNECTOR_CATEGORIES: readonly string[] = [
  ...new Set(CONNECTORS.map((connector) => connector.category)),
].sort();

/** Experience tokens actually present in the subset, in canonical
 * EXPERIENCE_CATEGORIES order (facets are built from real tokens, never an
 * imagined list). */
export const PRESENT_EXPERIENCES: readonly ExperienceToken[] =
  EXPERIENCE_CATEGORIES.filter((experience) =>
    CONNECTORS.some((connector) => connector.experience === experience),
  );

/** Short public label per real readiness token. credential_waiting — the state
 * every listed family is in today — reads as "Credentials required". */
export const CONNECTOR_STATUS_LABELS: Readonly<
  Record<ConnectorReadiness, string>
> = {
  scaffolded: "Scaffolded",
  disabled: "Disabled",
  degraded: "Degraded",
  credential_waiting: "Credentials required",
  replay_validated: "Replay validated",
  sandbox_validated: "Sandbox validated",
  partner_live: "Partner live",
};

/**
 * Boundary family aliases (shared/integration_contracts/aliases.py FAMILY_ALIASES,
 * ADR-0009) → canonical catalog family. The directory keys on canonical families
 * only; this mirror lets public copy/docs resolve a legacy name without
 * fabricating a row for it.
 */
export const FAMILY_ALIASES: Readonly<Record<string, string>> = {
  // shared/providers/categories.py AD_PLATFORM + recommendations emit
  // twitter_ads; the measurement runtime and catalog family is x_ads.
  twitter_ads: "x_ads",
  // Legacy naming for the Google Analytics 4 inbound connector (registry keys
  // it ga4).
  google_analytics: "ga4",
  // shared/providers marketing alias; the measurement runtime is meta_ads.
  facebook_ads: "meta_ads",
  // Campaign normalization maps bing/bing_ads → microsoft_ads; catalog family is
  // microsoft_ads.
  bing_ads: "microsoft_ads",
};

/** Public ad-platform family names with NO backed runtime (aliases.py
 * ALIAS_ONLY_FAMILIES): naming them is fine, claiming capability behind them is
 * not. None appears as a directory row — asserting that is a drift test. */
export const ALIAS_ONLY_FAMILIES: readonly string[] = [
  "snapchat_ads",
  "pinterest_ads",
];

/** Resolve a boundary family id to its canonical catalog family (mirror of
 * aliases.py canonical_family_id). */
export function canonicalFamilyId(id: string): string {
  const token = (id ?? "").trim().toLowerCase();
  if (token === "") return token;
  return FAMILY_ALIASES[token] ?? token;
}

/** Look up one connectable family by its canonical family id. */
export function findConnector(id: string): ConnectorRecord | undefined {
  return CONNECTORS.find((connector) => connector.id === id);
}
